//! App logos next to container names, from Dozzle's icon set (`app_logos_data.rs`,
//! generated by `scripts/import-dozzle-icons.py`).
//!
//! Drawn with the kitty graphics protocol's Unicode placeholders: each logo is
//! uploaded once as a virtual placement 2 cells wide, then drawn by writing
//! placeholder characters (U+10EEEE) whose foreground color carries the image id.
//! To ratatui those are ordinary text, so scrolling, sorting, popups and the
//! hyperlink overlay all keep working, and the protocol is in-band, so it works
//! over SSH. kitty (>= 0.28), Ghostty and Rex draw placeholders; other terminals
//! get no logos.

use std::collections::{HashMap, HashSet};

use base64::Engine;
use base64::engine::general_purpose::STANDARD as BASE64;
use ratatui::style::Color;

use crate::core::app_state::AppState;
use crate::core::types::ContainerKey;

use super::app_logos_data::{ALIASES, DISTRIBUTORS, GENERIC, LOGOS, SUFFIXES};

/// Columns a logo takes, including the space before the name
pub const LOGO_WIDTH: u16 = 3;

/// A logo's two placeholder cells: U+10EEEE, then diacritics for row 0 and
/// column 0 or 1
pub const PLACEHOLDER: &str = "\u{10EEEE}\u{0305}\u{0305}\u{10EEEE}\u{0305}\u{030D}";

/// Image ids are this plus the logo's index, kept clear of small ids that
/// other programs in the same terminal are likely to use. Fits in 24 bits,
/// which the placeholder's foreground color carries.
const ID_BASE: u32 = 0xD7_0000;

/// Whether the terminal, named by its XTVERSION reply, draws kitty Unicode
/// placeholders. Under tmux or screen the reply names the multiplexer (or there
/// is none), so logos stay off there.
pub fn terminal_supports_logos(name: Option<&str>) -> bool {
    let Some(name) = name else {
        return false;
    };
    let lower = name.to_ascii_lowercase();
    if lower.starts_with("ghostty") || lower == "rex" || lower.starts_with("rex ") {
        return true;
    }
    // kitty replies `kitty(0.36.4)`; placeholders came in 0.28
    if let Some(version) = lower.strip_prefix("kitty(") {
        let mut parts = version
            .split(['.', ')'])
            .map(|p| p.parse::<u32>().unwrap_or(0));
        let major = parts.next().unwrap_or(0);
        let minor = parts.next().unwrap_or(0);
        return (major, minor) >= (0, 28);
    }
    false
}

/// A logo: its index in [`LOGOS`]
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct Logo(usize);

impl Logo {
    pub fn image_id(self) -> u32 {
        ID_BASE + self.0 as u32 + 1
    }

    /// The foreground color that makes placeholder cells draw this logo
    pub fn color(self) -> Color {
        let id = self.image_id();
        Color::Rgb((id >> 16) as u8, (id >> 8) as u8, id as u8)
    }

    #[cfg(test)]
    fn slug(self) -> &'static str {
        LOGOS[self.0].0
    }

    /// Escape sequences that upload the logo and create its 2x1 virtual
    /// placement, chunked as the protocol requires. `q=2` keeps the terminal
    /// from answering, since nothing reads replies after startup.
    pub fn upload(self) -> String {
        let data = BASE64.encode(LOGOS[self.0].1);
        let mut out = String::with_capacity(data.len() + 64);
        let chunks: Vec<&str> = data
            .as_bytes()
            .chunks(4096)
            .map(|c| std::str::from_utf8(c).unwrap_or_default())
            .collect();
        for (i, chunk) in chunks.iter().enumerate() {
            let more = u8::from(i + 1 < chunks.len());
            if i == 0 {
                out.push_str(&format!(
                    "\x1b_Ga=T,U=1,f=100,i={},c=2,r=1,q=2,m={more};{chunk}\x1b\\",
                    self.image_id()
                ));
            } else {
                out.push_str(&format!("\x1b_Gm={more};{chunk}\x1b\\"));
            }
        }
        out
    }

    /// Escape sequence that frees the uploaded image
    pub fn delete(self) -> String {
        format!("\x1b_Ga=d,d=I,i={},q=2\x1b\\", self.image_id())
    }
}

/// Tracks which logos the terminal already has, so each is uploaded once
pub struct Uploads {
    enabled: bool,
    light_background: bool,
    sent: HashSet<Logo>,
    /// Each container's logo, matched once: a container's image never changes
    resolved: HashMap<ContainerKey, Option<Logo>>,
}

impl Uploads {
    pub fn new(enabled: bool, light_background: bool) -> Self {
        Self {
            enabled,
            light_background,
            sent: HashSet::new(),
            resolved: HashMap::new(),
        }
    }

    /// Uploads for logos of containers in `state` that the terminal doesn't
    /// have yet. Written before each frame, so a logo is there before its
    /// placeholder cells are drawn.
    pub fn pending(&mut self, state: &AppState) -> String {
        let mut out = String::new();
        if !self.enabled {
            return out;
        }
        // Every container, not just listed ones: the list is re-filtered during
        // the draw that follows, so a container that becomes listed then must
        // already have its logo. The cache keeps this to one lookup each.
        for (key, container) in &state.containers {
            let light_background = self.light_background;
            let logo = *self.resolved.entry(key.clone()).or_insert_with(|| {
                container
                    .image
                    .as_deref()
                    .and_then(|image| logo_for_image(image, light_background))
            });
            if let Some(logo) = logo
                && self.sent.insert(logo)
            {
                out.push_str(&logo.upload());
            }
        }
        // Forget containers that are gone, now and then rather than every frame
        if self.resolved.len() > 2 * state.containers.len() + 16 {
            self.resolved
                .retain(|key, _| state.containers.contains_key(key));
        }
        out
    }

    /// Forgets what was uploaded, so the next frame uploads every logo again.
    /// For when the terminal dropped its images (dtop re-entered the
    /// alternate screen after a shell session)
    pub fn forget_sent(&mut self) {
        self.sent.clear();
    }

    /// Frees every uploaded logo, for when dtop exits
    pub fn delete_all(&self) -> String {
        self.sent.iter().map(|logo| logo.delete()).collect()
    }
}

/// The logo for an image reference, matched exactly as Dozzle's `iconSlugForImage`
/// does, then switched to the `-dark` (for light backgrounds) or `-light` (for
/// dark ones) artwork where there is one. Doesn't allocate, since it runs for
/// every visible row on every frame.
pub fn logo_for_image(image: &str, light_background: bool) -> Option<Logo> {
    let index = slug_index_for_image(image)?;
    let slug = LOGOS[index].0;
    let variant = if light_background { "-dark" } else { "-light" };
    let themed = LOGOS
        .binary_search_by(|(key, _)| key.chars().cmp(slug.chars().chain(variant.chars())))
        .ok();
    Some(Logo(themed.unwrap_or(index)))
}

fn slug_index_for_image(image: &str) -> Option<usize> {
    // Drop the digest, then the tag. The tag test is anchored past the last
    // slash so a registry port ("registry:5000/app") isn't mistaken for one.
    let mut reference = image.split('@').next().unwrap_or_default();
    if let Some(colon) = reference.rfind(':')
        && reference.rfind('/').is_none_or(|slash| colon > slash)
    {
        reference = &reference[..colon];
    }

    let segments = || reference.split('/').filter(|s| !s.is_empty());
    let count = segments().count();
    // Registry hosts carry a dot or a port, except for localhost
    let has_host = count > 1
        && segments().next().is_some_and(|first| {
            first.contains(['.', ':']) || first.eq_ignore_ascii_case("localhost")
        });
    let usable = count - usize::from(has_host);

    // Nearest segment wins: `linuxserver/sonarr` is Sonarr, not LinuxServer
    for name in reference
        .rsplit('/')
        .filter(|s| !s.is_empty())
        .take(usable.min(2))
    {
        if contains(GENERIC, name) || contains(DISTRIBUTORS, name) {
            continue;
        }
        let stripped = strip_suffix(name);
        for candidate in [alias(name), Some(name), alias(stripped), Some(stripped)] {
            if let Some(index) = candidate.and_then(logo_index) {
                return Some(index);
            }
        }
    }
    None
}

/// An image name compared as Dozzle normalizes it: lowercase, `_` as `-`
fn normalized(name: &str) -> impl Iterator<Item = char> + '_ {
    name.chars().map(|c| {
        if c == '_' {
            '-'
        } else {
            c.to_ascii_lowercase()
        }
    })
}

fn contains(sorted: &[&str], name: &str) -> bool {
    sorted
        .binary_search_by(|key| key.chars().cmp(normalized(name)))
        .is_ok()
}

fn alias(name: &str) -> Option<&'static str> {
    ALIASES
        .binary_search_by(|(key, _)| key.chars().cmp(normalized(name)))
        .ok()
        .map(|i| ALIASES[i].1)
}

fn logo_index(name: &str) -> Option<usize> {
    LOGOS
        .binary_search_by(|(key, _)| key.chars().cmp(normalized(name)))
        .ok()
}

/// `name` without a deployment suffix (`-alpine`, `-server`, ...), unless that
/// would leave a single character
fn strip_suffix(name: &str) -> &str {
    for suffix in SUFFIXES {
        let Some(cut) = name.len().checked_sub(suffix.len() + 1) else {
            continue;
        };
        // A cut inside a multi-byte character can't be a suffix match
        let Some((rest, tail)) = name.split_at_checked(cut) else {
            continue;
        };
        if normalized(tail).eq(std::iter::once('-').chain(suffix.chars())) {
            return if rest.len() > 1 { rest } else { name };
        }
    }
    name
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn forget_sent_drops_every_upload() {
        let mut uploads = Uploads::new(true, false);
        uploads.sent.insert(Logo(0));
        assert!(!uploads.delete_all().is_empty());
        uploads.forget_sent();
        assert!(uploads.sent.is_empty());
        assert_eq!(uploads.delete_all(), "");
    }

    fn slug(image: &str) -> Option<&'static str> {
        slug_index_for_image(image).map(|i| LOGOS[i].0)
    }

    #[test]
    fn tables_are_sorted_for_binary_search() {
        assert!(LOGOS.windows(2).all(|w| w[0].0 < w[1].0));
        assert!(ALIASES.windows(2).all(|w| w[0].0 < w[1].0));
        assert!(DISTRIBUTORS.windows(2).all(|w| w[0] < w[1]));
        assert!(GENERIC.windows(2).all(|w| w[0] < w[1]));
    }

    #[test]
    fn matches_images_like_dozzle() {
        assert_eq!(slug("nginx"), Some("nginx"));
        assert_eq!(slug("nginx:1.27-alpine"), Some("nginx"));
        assert_eq!(slug("docker.io/library/postgres:16"), Some("postgresql"));
        assert_eq!(slug("lscr.io/linuxserver/sonarr:latest"), Some("sonarr"));
        assert_eq!(slug("ghcr.io/goauthentik/server:2024.2"), Some("authentik"));
        assert_eq!(slug("amir20/dozzle:latest"), Some("dozzle"));
        assert_eq!(slug("registry:5000/redis"), Some("redis"));
        assert_eq!(slug("localhost/grafana/grafana"), Some("grafana"));
        assert_eq!(slug("redis@sha256:abc"), Some("redis"));
        // Case and underscores are normalized
        assert_eq!(
            slug("Home_Assistant/home-assistant"),
            Some("home-assistant")
        );
        // Suffix stripping
        assert_eq!(slug("vaultwarden/server"), Some("vaultwarden"));
    }

    #[test]
    fn unknown_and_generic_images_have_no_logo() {
        assert_eq!(slug("mycompany/internal-tool"), None);
        assert_eq!(slug("server"), None);
        assert_eq!(slug("linuxserver/app"), None);
        assert_eq!(slug(""), None);
        // Non-ASCII names don't panic when a suffix cut lands inside a character
        assert_eq!(slug("aéalpine"), None);
        assert_eq!(strip_suffix("aéalpine"), "aéalpine");
        assert_eq!(slug("ü"), None);
        assert_eq!(slug("日本語サーバー"), None);
    }

    #[test]
    fn themed_variant_follows_the_background() {
        let dark_bg = logo_for_image("mintplex/anythingllm", false).unwrap();
        let light_bg = logo_for_image("mintplex/anythingllm", true).unwrap();
        assert_eq!(dark_bg.slug(), "anything-llm-light");
        // No -dark variant, so light backgrounds get the plain logo
        assert_eq!(light_bg.slug(), "anything-llm");
        assert_eq!(logo_for_image("nginx", true).unwrap().slug(), "nginx");
    }

    #[test]
    fn placeholder_color_carries_the_image_id() {
        let logo = logo_for_image("nginx", false).unwrap();
        let id = logo.image_id();
        assert_eq!(logo.color(), Color::Rgb(0xD7, (id >> 8) as u8, id as u8));
        assert!(id > ID_BASE && id < 1 << 24);
    }

    #[test]
    fn upload_is_chunked_and_quiet() {
        let logo = logo_for_image("nginx", false).unwrap();
        let upload = logo.upload();
        assert!(upload.starts_with(&format!(
            "\x1b_Ga=T,U=1,f=100,i={},c=2,r=1,q=2,m=",
            logo.image_id()
        )));
        assert!(upload.ends_with("\x1b\\"));
        // Every chunk carries at most 4096 bytes of payload
        for chunk in upload.split("\x1b_G").skip(1) {
            let payload = chunk.split_once(';').unwrap().1.trim_end_matches("\x1b\\");
            assert!(payload.len() <= 4096);
        }
        assert!(upload.contains("m=0;"));
    }

    #[test]
    fn supported_terminals() {
        assert!(terminal_supports_logos(Some("rex 0.0.1793645657-gd018d2")));
        assert!(terminal_supports_logos(Some("ghostty 1.3.2")));
        assert!(terminal_supports_logos(Some("kitty(0.28.0)")));
        assert!(!terminal_supports_logos(Some("kitty(0.27.1)")));
        assert!(!terminal_supports_logos(Some("WezTerm 20240203")));
        assert!(!terminal_supports_logos(Some("tmux 3.4")));
        assert!(!terminal_supports_logos(Some("rexterm 1.0")));
        assert!(!terminal_supports_logos(None));
    }
}
